const since = Date.now() - 7 * 864e5;
return $input.all().map(i => i.json)
  .filter(p => p.status === 'published' && ['facebook', 'instagram'].includes(p.platform) && p.post_id && new Date(p.published_at).getTime() >= since)
  .map(p => ({ json: p }));

const p = $('Last week\'s Meta posts').item.json;
const v = Object.fromEntries((($json.data) || []).map(m => [m.name, m.values?.[0]?.value ?? m.total_value?.value ?? 0]));
return { post_key: p.post_key,
  reach: v.reach ?? v.post_impressions_unique ?? 0,
  engagement: v.total_interactions ?? v.post_engaged_users ?? 0,
  clicks: v.post_clicks ?? 0 };

const keys = new Set($('Metrics').all().map(i => i.json.post_key));
const posts = $('Read Posts').all().map(i => i.json).filter(p => keys.has(p.post_key));
const m = Object.fromEntries($('Metrics').all().map(i => [i.json.post_key, i.json]));
const add = (acc, k, x) => { acc[k] = acc[k] || { posts: 0, reach: 0, engagement: 0, clicks: 0 };
  acc[k].posts++; acc[k].reach += +x.reach || 0; acc[k].engagement += +x.engagement || 0; acc[k].clicks += +x.clicks || 0; return acc; };
const byPlatform = {}, byPillar = {};
for (const p of posts) { add(byPlatform, p.platform, m[p.post_key]); add(byPillar, p.pillar, m[p.post_key]); }
const best = posts.map(p => ({ ...p, ...m[p.post_key] })).sort((a, b) => b.reach - a.reach)[0];
return [{ json: { count: posts.length, byPlatform, byPillar, best: best ? `${best.platform} · ${best.pillar} · reach ${best.reach}: ${String(best.caption).slice(0, 100)}` : 'none' } }];

