const t = $('Totals by platform and pillar').first().json;
const lines = Object.entries(t.byPillar).map(([k, v]) => `${k}: ${v.posts} posts, reach ${v.reach}, clicks ${v.clicks}`);
const text = [`Last week · ${t.count} Facebook/Instagram posts measured`, `Best: ${t.best}`, 'By pillar:', ...lines, '', 'Plan change: ' + String($json.text || '').trim()].join('\n');
return [{ json: { text } }];
